    (Quest (tens (var "B") (covar "C")) (Quest (tens (var "A") (covar "B")) (Quest (covar "A") (Copy (covar "A") (Copy (tens (var "A") (covar "B")) (Tensor (var "A") (covar "B") (Ax "A") (Copy (tens (var "B") (covar "C")) (Tensor (var "B") (covar "C") (Ax "B") (Copy (covar "A") (Copy (tens (var "A") (covar "B")) (Tensor (var "A") (covar "B") (Ax "A") (Copy (tens (var "B") (covar "C")) (Tensor (var "B") (covar "C") (Ax "B") (Copy (covar "A") (Copy (tens (var "A") (covar "B")) (Tensor (var "A") (covar "B") (Ax "A") (Copy (tens (var "B") (covar "C")) (Tensor (var "B") (covar "C") (Ax "B") (Copy (covar "A") (Copy (tens (var "A") (covar "B")) (Tensor (var "A") (covar "B") (Ax "A") (Copy (tens (var "B") (covar "C")) (Tensor (var "B") (covar "C") (Ax "B") (Tensor (tens (tens (var "C") (var "C")) (var "C")) (var "C") (Tensor (tens (var "C") (var "C")) (var "C") (Tensor (var "C") (var "C") (Ax "C") (Ax "C")) (Ax "C")) (Ax "C")))))))))))))))))))))))))).
  vm_compute. reflexivity.
Qed.

