    (Par (covar "A") (awith (covar "B") (covar "C")) (With (covar "B") (covar "C") (Plus (tens (var "A") (var "B")) (tens (var "A") (var "C")) Left (Tensor (var "A") (var "B") (Ax "A") (Ax "B"))) (Plus (tens (var "A") (var "B")) (tens (var "A") (var "C")) Right (Tensor (var "A") (var "C") (Ax "A") (Ax "C")))))).
  vm_compute. reflexivity.
Qed.

